#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const DEFAULT_FILE = 'README.md';
const TODO_STRING_PATTERN = /TODO(?::[^\s]+)?/g;

function countOccurrences(text, needle) {
  if (needle.length === 0) {
    return 0;
  }
  let count = 0;
  let index = text.indexOf(needle);
  while (index !== -1) {
    count += 1;
    index = text.indexOf(needle, index + needle.length);
  }
  return count;
}

function collectTodoStrings(text) {
  const strings = [];
  const seen = new Set();
  for (const match of text.matchAll(TODO_STRING_PATTERN)) {
    if (!seen.has(match[0])) {
      seen.add(match[0]);
      strings.push(match[0]);
    }
  }
  return strings;
}

function countTodos(text) {
  return collectTodoStrings(text).map((todo) => ({
    todo,
    count: countOccurrences(text, todo),
  }));
}

function formatTable(results) {
  const width = results.reduce((max, result) => Math.max(max, result.todo.length), 0);
  return results
    .map((result) => `${result.todo.padEnd(width)}  ${result.count}`)
    .join('\n');
}

function resolveFile(file) {
  if (file === undefined) {
    return path.resolve(__dirname, DEFAULT_FILE);
  }
  return path.resolve(process.cwd(), file);
}

function parseArgs(argv) {
  const options = { file: undefined, json: false, help: false };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--json') {
      options.json = true;
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    } else if (arg === '--file' || arg === '-f') {
      options.file = argv[i + 1];
      i += 1;
    } else if (arg.startsWith('-')) {
      throw new Error(`Unknown option: ${arg}`);
    } else if (options.file === undefined) {
      options.file = arg;
    } else {
      throw new Error(`Unexpected argument: ${arg}`);
    }
  }
  if (options.file === undefined && argv.some((arg) => arg === '--file' || arg === '-f')) {
    throw new Error('Missing value for --file');
  }
  return options;
}

function usage() {
  return [
    'Usage: todo-cli [file] [--json]',
    '',
    'Counts how often each TODO string occurs in the document,',
    'matching the text literally and including the sentence that',
    'defines them.',
    '',
    'Options:',
    `  -f, --file <path>  Document to scan (default: ${DEFAULT_FILE} next to this script)`,
    '      --json         Print the counts as JSON',
    '  -h, --help         Show this help',
  ].join('\n');
}

function main(argv) {
  const options = parseArgs(argv);
  if (options.help) {
    process.stdout.write(`${usage()}\n`);
    return 0;
  }

  const file = resolveFile(options.file);
  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch (error) {
    process.stderr.write(`todo-cli: cannot read ${file}: ${error.message}\n`);
    return 1;
  }

  const results = countTodos(text);
  if (options.json) {
    const total = results.reduce((sum, result) => sum + result.count, 0);
    process.stdout.write(
      `${JSON.stringify({ file, results, total }, null, 2)}\n`
    );
    return 0;
  }

  process.stdout.write(`${results.length > 0 ? `${formatTable(results)}\n` : ''}`);
  return 0;
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

module.exports = {
  collectTodoStrings,
  countOccurrences,
  countTodos,
  formatTable,
  main,
};

